'use strict';
window.TravelCitySearch=(()=>{
// Common Korean names that the geocoding index does not consistently match.
const aliases={런던:['London','GB'],파리:['Paris','FR'],서울:['Seoul','KR'],도쿄:['Tokyo','JP'],동경:['Tokyo','JP'],뉴욕:['New York','US'],로마:['Rome','IT'],방콕:['Bangkok','TH'],시드니:['Sydney','AU'],바르셀로나:['Barcelona','ES'],마드리드:['Madrid','ES'],리스본:['Lisbon','PT'],포르투:['Porto','PT'],베를린:['Berlin','DE'],뮌헨:['Munich','DE'],프랑크푸르트:['Frankfurt','DE'],암스테르담:['Amsterdam','NL'],프라하:['Prague','CZ'],빈:['Vienna','AT'],비엔나:['Vienna','AT'],부다페스트:['Budapest','HU'],취리히:['Zurich','CH'],제네바:['Geneva','CH'],밀라노:['Milan','IT'],베네치아:['Venice','IT'],베니스:['Venice','IT'],피렌체:['Florence','IT'],나폴리:['Naples','IT'],아테네:['Athens','GR'],이스탄불:['Istanbul','TR'],두바이:['Dubai','AE'],싱가포르:['Singapore','SG'],홍콩:['Hong Kong','HK'],타이베이:['Taipei','TW'],상하이:['Shanghai','CN'],베이징:['Beijing','CN'],오사카:['Osaka','JP'],교토:['Kyoto','JP'],후쿠오카:['Fukuoka','JP'],삿포로:['Sapporo','JP'],부산:['Busan','KR'],제주:['Jeju','KR'],경주:['Gyeongju','KR'],강릉:['Gangneung','KR'],전주:['Jeonju','KR'],대구:['Daegu','KR'],인천:['Incheon','KR'],다낭:['Da Nang','VN'],하노이:['Hanoi','VN'],호치민:['Ho Chi Minh City','VN'],치앙마이:['Chiang Mai','TH'],푸켓:['Phuket','TH'],쿠알라룸푸르:['Kuala Lumpur','MY'],로스앤젤레스:['Los Angeles','US'],샌프란시스코:['San Francisco','US'],라스베이거스:['Las Vegas','US'],보스턴:['Boston','US'],시카고:['Chicago','US'],시애틀:['Seattle','US'],워싱턴:['Washington','US'],밴쿠버:['Vancouver','CA'],토론토:['Toronto','CA'],몬트리올:['Montreal','CA'],멜버른:['Melbourne','AU'],오클랜드:['Auckland','NZ'],암허스트:['Amherst','US'],애머스트:['Amherst','US']};
function normalize(query){const text=query.normalize('NFKC').trim(),alias=aliases[text.replace(/\s+/g,'')];return{name:alias?.[0]||text,country:alias?.[1]}}
async function search(query,count=10){const q=normalize(query),language=window.AppI18n?.locale==='ko'?'ko':'en';const params=new URLSearchParams({name:q.name,count:String(count),language,format:'json'});const response=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+params,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('City search unavailable');const body=await response.json();return(body.results||[]).sort((a,b)=>Number(b.country_code===q.country)-Number(a.country_code===q.country))}
return{search,normalize};})();
